45	fn rejected(reason: &'static str, did: &str, signing_key: &str) -> ApiError {
46	    tracing::warn!(
47	        reason,
48	        account_did = %did,
49	        signing_key_did = %signing_key,
50	        "sovereign session proof rejected"
51	    );
52	    ApiError::new(ErrorCode::AuthenticationRequired, REJECTION_MESSAGE)
53	}
54	
55	fn decode_canonical_base64url(value: &str, expected_len: usize) -> Option<Vec<u8>> {
56	    let decoded = URL_SAFE_NO_PAD.decode(value).ok()?;
57	    (decoded.len() == expected_len && URL_SAFE_NO_PAD.encode(&decoded) == value).then_some(decoded)
58	}
59	
60	fn is_plc_did(value: &str) -> bool {
61	    let Some(suffix) = value.strip_prefix("did:plc:") else {
62	        return false;
63	    };
64	    suffix.len() == 24
65	        && suffix
66	            .bytes()
67	            .all(|byte| byte.is_ascii_lowercase() || (b'2'..=b'7').contains(&byte))
68	}
69	
70	fn unix_timestamp() -> Result<i64, ApiError> {
71	    let seconds = SystemTime::now()
72	        .duration_since(UNIX_EPOCH)
73	        .map_err(|e| {
74	            tracing::error!(error = %e, "system clock is before Unix epoch");
75	            ApiError::new(
76	                ErrorCode::InternalError,
77	                "failed to verify request timestamp",
78	            )
79	        })?
80	        .as_secs();
81	    i64::try_from(seconds).map_err(|_| {
82	        ApiError::new(
83	            ErrorCode::InternalError,
84	            "system timestamp exceeds supported range",
85	        )
86	    })
87	}
