89	/// Exchange proof from any key in a hosted DID's authoritative current PLC rotation set for a
90	/// standard full-access Custos session.
91	///
92	/// A Custos-held rotation key qualifies under exactly the same PLC semantics as any other current
93	/// rotation key. This grants Custos no additional hosting power over an account it already hosts.
94	pub async fn create_sovereign_session(
95	    State(state): State<AppState>,
96	    Json(request): Json<SovereignSessionRequest>,
97	) -> Result<(StatusCode, Json<SovereignSessionResponse>), ApiError> {
98	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
99	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
100	        .ok_or_else(|| {
101	            rejected(
102	                "invalid_signature_encoding",
103	                &request.did,
104	                &request.signing_key,
105	            )
106	        })?;
107	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
108	        return Err(rejected(
109	            "invalid_nonce_encoding",
110	            &request.did,
111	            &request.signing_key,
112	        ));
113	    }
114	    if !is_plc_did(&request.did) {
115	        return Err(rejected(
116	            "invalid_account_did",
117	            &request.did,
118	            &request.signing_key,
119	        ));
120	    }
121	
122	    let now = unix_timestamp()?;
123	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
124	        return Err(rejected(
125	            "timestamp_outside_window",
126	            &request.did,
127	            &request.signing_key,
128	        ));
129	    }
130	
131	    // This cheap local gate precedes signature verification and the outbound PLC lookup. Missing
132	    // and every inactive lifecycle state intentionally share one response.
133	    if !active_local_account_exists(&state.db, &request.did).await? {
134	        return Err(rejected(
135	            "account_not_active_local",
136	            &request.did,
137	            &request.signing_key,
138	        ));
139	    }
140	
141	    let server_did = state.config.resolve_server_did();
142	    let envelope = crypto::encode_sovereign_session_envelope(
143	        &server_did,
144	        &request.did,
145	        &request.signing_key,
146	        request.timestamp,
147	        &request.nonce,
148	    );
149	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
150	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature).map_err(|_| {
151	        rejected(
152	            "signature_verification_failed",
153	            &request.did,
154	            &request.signing_key,
155	        )
156	    })?;
157	
158	    // rotationKeys is authoritative only in the latest non-nullified PLC audit-log operation. The
159	    // locally cached W3C DID document is deliberately not consulted here.
160	    let plc = fetch_current_plc_state(
161	        &state.http_client,
162	        &state.config.plc_directory_url,
163	        &request.did,
164	    )
165	    .await?;
166	    if !plc
167	        .rotation_keys
168	        .iter()
169	        .any(|key| key == &request.signing_key)
170	    {
171	        return Err(rejected(
172	            "signing_key_not_current_rotation_key",
173	            &request.did,
174	            &request.signing_key,
175	        ));
176	    }
177	
178	    // The lifecycle recheck, one-time nonce insertion, and both session rows share one SQLite
179	    // transaction. A replay or a concurrent deactivation therefore cannot mint a partial session.
180	    let mut tx = state.db.begin().await.map_err(|e| {
181	        tracing::error!(error = %e, account_did = %request.did, "failed to begin sovereign session transaction");
182	        ApiError::new(ErrorCode::InternalError, "failed to create session")
183	    })?;
184	    if !active_local_account_exists(&mut *tx, &request.did).await? {
185	        return Err(rejected(
186	            "account_became_inactive",
187	            &request.did,
188	            &request.signing_key,
189	        ));
190	    }
191	    if !insert_nonce_if_absent(&mut *tx, &request.did, &request.nonce)
192	        .await
193	        .map_err(|e| {
194	            tracing::error!(error = %e, account_did = %request.did, "failed to consume sovereign nonce");
195	            ApiError::new(ErrorCode::InternalError, "failed to create session")
196	        })?
197	    {
198	        return Err(rejected(
199	            "nonce_replay",
200	            &request.did,
201	            &request.signing_key,
202	        ));
203	    }
204	    let issued =
205	        issue_session_in_transaction(&mut tx, &state, &request.did, &SessionKind::FullAccess)
206	            .await?;
207	    tx.commit().await.map_err(|e| {
208	        tracing::error!(error = %e, account_did = %request.did, "failed to commit sovereign session transaction");
209	        ApiError::new(ErrorCode::InternalError, "failed to create session")
210	    })?;
211	
212	    tracing::info!(
213	        account_did = %request.did,
214	        signing_key_did = %request.signing_key,
215	        plc_head = %plc.cid,
216	        "sovereign full-access session issued"
217	    );
218	    Ok((
219	        StatusCode::OK,
220	        Json(SovereignSessionResponse {
221	            access_jwt: issued.access_jwt,
222	            refresh_jwt: issued.refresh_jwt,
223	            handle: issued.handle,
224	            did: issued.did,
225	            email: issued.email,
226	        }),
227	    ))
228	}
