284	    fn p256_key() -> TestKey {
285	        let generated = crypto::generate_p256_keypair().unwrap();
286	        let signing_key = P256SigningKey::from_bytes(generated.private_key_bytes.as_slice().into())
287	            .expect("valid P-256 scalar");
288	        TestKey {
289	            did: generated.key_id.0,
290	            sign: Box::new(move |message| {
291	                let sig: P256Signature = signing_key.sign(message);
292	                URL_SAFE_NO_PAD.encode(sig.normalize_s().unwrap_or(sig).to_bytes())
293	            }),
294	        }
295	    }
296	
297	    fn secp256k1_key() -> TestKey {
298	        let signing_key = k256::ecdsa::SigningKey::random(&mut OsRng);
299	        let mut multikey = vec![0xe7, 0x01];
300	        multikey.extend_from_slice(
301	            signing_key
302	                .verifying_key()
303	                .to_encoded_point(true)
304	                .as_bytes(),
305	        );
306	        let did = format!(
307	            "did:key:{}",
308	            multibase::encode(multibase::Base::Base58Btc, multikey)
309	        );
310	        TestKey {
311	            did,
312	            sign: Box::new(move |message| {
313	                let sig: K256Signature = signing_key.sign(message);
314	                URL_SAFE_NO_PAD.encode(sig.normalize_s().unwrap_or(sig).to_bytes())
315	            }),
316	        }
317	    }
