367	    fn proof_body(state: &AppState, key: &TestKey, did: &str, timestamp: i64, fill: u8) -> Value {
368	        let nonce = URL_SAFE_NO_PAD.encode([fill; NONCE_BYTES]);
369	        let envelope = crypto::encode_sovereign_session_envelope(
370	            &state.config.resolve_server_did(),
371	            did,
372	            &key.did,
373	            timestamp,
374	            &nonce,
375	        );
376	        json!({
377	            "did": did,
378	            "signingKey": key.did,
379	            "timestamp": timestamp,
380	            "nonce": nonce,
381	            "signature": (key.sign)(&envelope)
382	        })
383	    }
