385	    fn post(body: Value) -> Request<Body> {
386	        Request::builder()
387	            .method("POST")
388	            .uri(crypto::SOVEREIGN_SESSION_PATH)
389	            .header("content-type", "application/json")
390	            .body(Body::from(serde_json::to_vec(&body).unwrap()))
391	            .unwrap()
392	    }
