394	    async fn assert_success_for_key(key: TestKey) {
395	        let plc = MockServer::start().await;
396	        let state = state_with_plc(&plc).await;
397	        let did = "did:plc:aaaaaaaaaaaaaaaaaaaaaaaa";
398	        seed_account(&state, did).await;
399	        mount_audit_log(&plc, did, &[&key.did]).await;
400	
401	        let response = app(state.clone())
402	            .oneshot(post(proof_body(&state, &key, did, now(), 1)))
403	            .await
404	            .unwrap();
405	        assert_eq!(response.status(), StatusCode::OK);
406	        let body = body_json(response).await;
407	        assert_eq!(body["did"], did);
408	        assert_eq!(body["handle"], "owner.example.com");
409	        assert_eq!(body["email"], "owner@example.com");
410	        assert!(body["refreshJwt"].is_string());
411	        let claims =
412	            verify_hs256_access_token(body["accessJwt"].as_str().unwrap(), &state).unwrap();
413	        assert_eq!(parse_scope(&claims.scope).unwrap(), AuthScope::Access);
414	    }
