446	    #[tokio::test]
447	    async fn every_envelope_binding_is_signature_protected() {
448	        let plc = MockServer::start().await;
449	        let state = state_with_plc(&plc).await;
450	        let did = "did:plc:cccccccccccccccccccccccc";
451	        let key = p256_key();
452	        seed_account(&state, did).await;
453	        sqlx::query(
454	            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
455	             VALUES ('did:plc:dddddddddddddddddddddddd', 'other@example.com', NULL, datetime('now'), datetime('now'))",
456	        )
457	        .execute(&state.db)
458	        .await
459	        .unwrap();
460	
461	        let timestamp = now();
462	        let base = proof_body(&state, &key, did, timestamp, 4);
463	        let other_key = p256_key();
464	        let mutations = [
465	            ("did", json!("did:plc:dddddddddddddddddddddddd")),
466	            ("signingKey", json!(other_key.did)),
467	            ("timestamp", json!(timestamp - 1)),
468	            ("nonce", json!(URL_SAFE_NO_PAD.encode([5u8; NONCE_BYTES]))),
469	        ];
470	        for (field, value) in mutations {
471	            let mut changed = base.clone();
472	            changed[field] = value;
473	            let response = app(state.clone()).oneshot(post(changed)).await.unwrap();
474	            assert_eq!(response.status(), StatusCode::UNAUTHORIZED, "field {field}");
475	        }
476	
477	        for wrong_envelope in [
478	            crypto::encode_sovereign_session_envelope(
479	                "did:web:other.example.com",
480	                did,
481	                &key.did,
482	                timestamp,
483	                base["nonce"].as_str().unwrap(),
484	            ),
485	            String::from_utf8(crypto::encode_sovereign_session_envelope(
486	                &state.config.resolve_server_did(),
487	                did,
488	                &key.did,
489	                timestamp,
490	                base["nonce"].as_str().unwrap(),
491	            ))
492	            .unwrap()
493	            .replace("method:4:POST", "method:3:GET")
494	            .into_bytes(),
495	            String::from_utf8(crypto::encode_sovereign_session_envelope(
496	                &state.config.resolve_server_did(),
497	                did,
498	                &key.did,
499	                timestamp,
500	                base["nonce"].as_str().unwrap(),
501	            ))
502	            .unwrap()
503	            .replace(
504	                "path:22:/v1/sessions/sovereign",
505	                "path:21:/v1/session/sovereign",
506	            )
507	            .into_bytes(),
508	        ] {
509	            let mut changed = base.clone();
510	            changed["signature"] = json!((key.sign)(&wrong_envelope));
511	            let response = app(state.clone()).oneshot(post(changed)).await.unwrap();
512	            assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
513	        }
514	    }
