19	/// Resolve a handle to a DID using ezpds' ATProto handle-resolution chain:
20	/// local handles table → DNS TXT `_atproto.<handle>` → HTTP `.well-known/atproto-did`.
21	///
22	/// Infrastructure errors in DNS / well-known are logged and treated as misses so later fallbacks
23	/// still get a chance to resolve the handle. Database errors fail closed.
24	pub async fn resolve_handle_to_did(
25	    state: &AppState,
26	    handle: &str,
27	) -> Result<Option<String>, ApiError> {
28	    super::handle::validate_handle_structure(handle)
29	        .map_err(|message| ApiError::new(ErrorCode::InvalidHandle, message))?;
30	
31	    let row: Option<(String,)> = sqlx::query_as("SELECT did FROM handles WHERE handle = ?")
32	        .bind(handle)
33	        .fetch_optional(&state.db)
34	        .await
35	        .map_err(|e| {
36	            tracing::error!(error = %e, handle = %handle, "failed to query handle");
37	            ApiError::new(ErrorCode::InternalError, "handle lookup failed")
38	        })?;
39	
40	    if let Some((did,)) = row {
41	        return Ok(Some(did));
42	    }
43	
44	    if let Some(resolver) = &state.txt_resolver {
45	        let name = format!("_atproto.{handle}");
46	        match resolver.txt_lookup(&name).await {
47	            Ok(records) => {
48	                let mut dids: Vec<&str> = records
49	                    .iter()
50	                    .filter_map(|r| r.strip_prefix("did="))
51	                    .collect();
52	                dids.sort_unstable();
53	                dids.dedup();
54	                match dids.as_slice() {
55	                    [] => {}
56	                    [did] => return Ok(Some((*did).to_string())),
57	                    _ => {
58	                        // Per the handle spec, multiple `did=` TXT records naming different
59	                        // DIDs is ambiguous — resolution must not pick one by DNS answer order.
60	                        // Fall through to well-known rather than fail closed, matching the
61	                        // lookup-error handling below.
62	                        tracing::warn!(
63	                            handle = %handle,
64	                            count = dids.len(),
65	                            "ambiguous _atproto TXT records (multiple distinct DIDs); falling through to well-known"
66	                        );
67	                    }
68	                }
69	            }
70	            Err(e) => {
71	                tracing::warn!(
72	                    error = %e,
73	                    handle = %handle,
74	                    "DNS TXT lookup failed; falling through to well-known"
75	                );
76	            }
77	        }
78	    }
79	
80	    if let Some(resolver) = &state.well_known_resolver {
81	        match resolver.resolve(handle).await {
82	            Ok(Some(did)) => return Ok(Some(did)),
83	            Ok(None) => {}
84	            Err(e) => {
85	                tracing::warn!(
86	                    error = %e,
87	                    handle = %handle,
88	                    "HTTP well-known lookup failed"
89	                );
90	            }
91	        }
92	    }
93	
94	    Ok(None)
95	}
