97	/// Resolve a DID to its current DID document, preferring the local cache.
98	///
99	/// Local cached documents are preferred. Unknown `did:plc` values are proxied to the configured PLC
100	/// directory; unknown `did:web` values are resolved through the method's `did.json` URL. Returned
101	/// documents must assert the requested DID in their `id` field.
102	pub async fn resolve_did_document(state: &AppState, did: &str) -> Result<Value, ApiError> {
103	    resolve_did_document_inner(state, did, false).await
104	}
105	
106	/// Resolve a DID to its current DID document, **bypassing the local cache** and rewriting any
107	/// existing cache row with the freshly-fetched document.
108	///
109	/// The `did_documents` cache is a persistent store with no TTL: a DID whose PLC document was
110	/// rewritten after this server cached it (e.g. an `#atproto` key rotation during an account's
111	/// identity-migration leg) is otherwise served against the fossil key forever. This is the
112	/// "force refresh" the reference PDS's `refreshIdentity` performs, and the retry the migration
113	/// `createAccount` verifier takes on a signature failure. On success the fresh document is written
114	/// back over the existing cache row (UPDATE-only — see [`crate::db::dids::rewrite_did_document`]),
115	/// so a subsequent cache-first read (including this server's own `resolveDid`/`getSession`)
116	/// reflects it.
117	pub async fn resolve_did_document_force_refresh(
118	    state: &AppState,
119	    did: &str,
120	) -> Result<Value, ApiError> {
121	    resolve_did_document_inner(state, did, true).await
122	}
123	
124	async fn resolve_did_document_inner(
125	    state: &AppState,
126	    did: &str,
127	    force_refresh: bool,
128	) -> Result<Value, ApiError> {
129	    if !did.starts_with("did:") {
130	        return Err(ApiError::new(ErrorCode::InvalidClaim, "invalid DID format"));
131	    }
132	
133	    if !force_refresh {
134	        if let Some(doc) = crate::db::dids::get_did_document(&state.db, did).await? {
135	            return validate_did_doc_id(doc, did, ErrorCode::InternalError);
136	        }
137	    }
138	
139	    let doc = if did.starts_with("did:plc:") {
140	        resolve_plc_did_document(state, did).await?
141	    } else if did.starts_with("did:web:") {
142	        resolve_web_did_document(state, did).await?
143	    } else {
144	        return Err(ApiError::new(ErrorCode::DidNotFound, "DID not found"));
145	    };
146	
147	    if force_refresh {
148	        // Heal the cached row so subsequent cache-first reads reflect the fresh document.
149	        // Best-effort: the authoritative source already answered, so a cache-write failure must
150	        // not fail the resolution.
151	        if let Err(e) = crate::db::dids::rewrite_did_document(&state.db, did, &doc).await {
152	            tracing::warn!(did = %did, error = %e, "failed to rewrite cached DID document after force refresh (non-fatal)");
153	        }
154	    }
155	
156	    Ok(doc)
157	}
