159	/// Return the verified handle for `did` and `did_doc`, or `handle.invalid` when the document's
160	/// `alsoKnownAs` handles do not resolve back to the DID.
161	pub async fn verified_handle_for_did(
162	    state: &AppState,
163	    did: &str,
164	    did_doc: &Value,
165	) -> Result<String, ApiError> {
166	    for handle in also_known_as_handles(did_doc) {
167	        if resolve_handle_to_did(state, &handle).await?.as_deref() == Some(did) {
168	            return Ok(handle);
169	        }
170	    }
171	
172	    Ok(INVALID_HANDLE.to_string())
173	}
