175	/// Verify a caller-provided handle against a DID document and the handle-resolution chain.
176	pub async fn verified_handle_for_identifier(
177	    state: &AppState,
178	    did: &str,
179	    did_doc: &Value,
180	    handle: &str,
181	) -> Result<String, ApiError> {
182	    let asserted = also_known_as_handles(did_doc)
183	        .into_iter()
184	        .any(|candidate| candidate == handle);
185	    if !asserted {
186	        return Ok(INVALID_HANDLE.to_string());
187	    }
188	
189	    if resolve_handle_to_did(state, handle).await?.as_deref() == Some(did) {
190	        Ok(handle.to_string())
191	    } else {
192	        Ok(INVALID_HANDLE.to_string())
193	    }
194	}
