196	async fn resolve_plc_did_document(state: &AppState, did: &str) -> Result<Value, ApiError> {
197	    let plc_url = format!(
198	        "{}/{}",
199	        state.config.plc_directory_url.trim_end_matches('/'),
200	        did
201	    );
202	    let response = state.http_client.get(&plc_url).send().await.map_err(|e| {
203	        tracing::error!(did = %did, error = %e, plc_url = %plc_url, "failed to contact plc.directory");
204	        ApiError::new(ErrorCode::PlcDirectoryError, "failed to contact plc.directory")
205	    })?;
206	
207	    if response.status() == reqwest::StatusCode::NOT_FOUND {
208	        tracing::debug!(did = %did, "DID not found in plc.directory");
209	        return Err(ApiError::new(ErrorCode::DidNotFound, "DID not found"));
210	    }
211	
212	    if response.status() == reqwest::StatusCode::GONE {
213	        tracing::debug!(did = %did, "DID deactivated in plc.directory");
214	        return Err(ApiError::new(ErrorCode::DidDeactivated, "DID deactivated"));
215	    }
216	
217	    if !response.status().is_success() {
218	        let status = response.status();
219	        let truncated = bounded_body_preview(response).await;
220	        tracing::error!(did = %did, status = %status, response_body = %truncated, "plc.directory returned error");
221	        return Err(ApiError::new(
222	            ErrorCode::PlcDirectoryError,
223	            "plc.directory returned error",
224	        ));
225	    }
226	
227	    let doc: Value = response.json().await.map_err(|e| {
228	        tracing::error!(did = %did, error = %e, "failed to parse plc.directory response");
229	        ApiError::new(
230	            ErrorCode::PlcDirectoryError,
231	            "invalid response from plc.directory",
232	        )
233	    })?;
234	
235	    validate_did_doc_id(doc, did, ErrorCode::PlcDirectoryError)
236	}
