238	pub(crate) async fn resolve_web_did_document(
239	    state: &AppState,
240	    did: &str,
241	) -> Result<Value, ApiError> {
242	    let url = did_web_document_url(did)?;
243	    // The did:web authority is caller-controlled (the requested `did`), so this fetch is
244	    // SSRF-guarded exactly like resolve_web_did_document_bytes: validate the endpoint's URL shape
245	    // (and, for an IP literal, its address), then send on the shared hardened client whose DNS
246	    // resolver re-checks any domain-name resolution against the allowlist at connect time.
247	    let authority = did_web_authority(&url)?;
248	    validate_proxy_endpoint(&authority, state.allow_loopback_proxy_targets).await?;
249	    let response = state.hardened_http_client.get(&url).send().await.map_err(|e| {
250	        tracing::error!(did = %did, error = %e, url = %url, "failed to resolve did:web document");
251	        ApiError::new(
252	            ErrorCode::PlcDirectoryError,
253	            "failed to resolve did:web document",
254	        )
255	    })?;
256	
257	    if response.status() == reqwest::StatusCode::NOT_FOUND {
258	        return Err(ApiError::new(ErrorCode::DidNotFound, "DID not found"));
259	    }
260	
261	    if response.status() == reqwest::StatusCode::GONE {
262	        tracing::debug!(did = %did, "DID deactivated at did:web endpoint");
263	        return Err(ApiError::new(ErrorCode::DidDeactivated, "DID deactivated"));
264	    }
265	
266	    if !response.status().is_success() {
267	        let status = response.status();
268	        let truncated = bounded_body_preview(response).await;
269	        tracing::error!(did = %did, status = %status, response_body = %truncated, "did:web endpoint returned error");
270	        return Err(ApiError::new(
271	            ErrorCode::PlcDirectoryError,
272	            "did:web endpoint returned error",
273	        ));
274	    }
275	
276	    let doc: Value = response.json().await.map_err(|e| {
277	        tracing::error!(did = %did, error = %e, "failed to parse did:web response");
278	        ApiError::new(ErrorCode::PlcDirectoryError, "invalid did:web response")
279	    })?;
280	
281	    validate_did_doc_id(doc, did, ErrorCode::PlcDirectoryError)
282	}
