325	const ERROR_BODY_PREVIEW_BYTES: usize = 2048;
326	
327	/// Read up to [`ERROR_BODY_PREVIEW_BYTES`] of an error response body for logging, instead of
328	/// buffering the whole thing — an erroneous upstream (plc.directory, a did:web endpoint) is not
329	/// trusted to bound its own response size. Shared with `identity::genesis`'s plc.directory POST.
330	pub(crate) async fn bounded_body_preview(mut response: reqwest::Response) -> String {
331	    let mut body = Vec::new();
332	    while body.len() < ERROR_BODY_PREVIEW_BYTES {
333	        let chunk = match response.chunk().await {
334	            Ok(Some(chunk)) => chunk,
335	            Ok(None) | Err(_) => break,
336	        };
337	        let remaining = ERROR_BODY_PREVIEW_BYTES - body.len();
338	        body.extend_from_slice(&chunk[..chunk.len().min(remaining)]);
339	    }
340	
341	    safe_body_preview(&String::from_utf8_lossy(&body))
342	}
343	
344	fn safe_body_preview(body: &str) -> String {
345	    body.chars().take(500).collect()
346	}
