348	/// Extract the `https://host[:port]` authority from an already-built did:web document URL, for the
349	/// SSRF `validate_proxy_endpoint` shape check. Shared by both did:web fetch paths.
350	fn did_web_authority(url: &str) -> Result<String, ApiError> {
351	    let parsed = reqwest::Url::parse(url)
352	        .map_err(|_| ApiError::new(ErrorCode::InvalidClaim, "invalid did:web DID"))?;
353	    parsed
354	        .host_str()
355	        .map(|host| match parsed.port() {
356	            Some(port) => format!("https://{host}:{port}"),
357	            None => format!("https://{host}"),
358	        })
359	        .ok_or_else(|| ApiError::new(ErrorCode::InvalidClaim, "invalid did:web DID"))
360	}
361	
362	fn did_web_document_url(did: &str) -> Result<String, ApiError> {
363	    let method_specific = did
364	        .strip_prefix("did:web:")
365	        .ok_or_else(|| ApiError::new(ErrorCode::InvalidClaim, "invalid did:web DID"))?;
366	    if method_specific.is_empty() {
367	        return Err(ApiError::new(
368	            ErrorCode::InvalidClaim,
369	            "invalid did:web DID",
370	        ));
371	    }
372	
373	    let segments = method_specific
374	        .split(':')
375	        .map(|segment| {
376	            urlencoding::decode(segment)
377	                .map(|decoded| decoded.into_owned())
378	                .map_err(|_| ApiError::new(ErrorCode::InvalidClaim, "invalid did:web DID"))
379	        })
380	        .collect::<Result<Vec<_>, _>>()?;
381	
382	    let Some(host) = segments.first() else {
383	        return Err(ApiError::new(
384	            ErrorCode::InvalidClaim,
385	            "invalid did:web DID",
386	        ));
387	    };
388	    if host.is_empty()
389	        || forbidden_did_web_authority(host)
390	        || segments.iter().any(|segment| {
391	            segment.is_empty()
392	                || segment.contains('/')
393	                || segment.contains('\\')
394	                || segment.contains('?')
395	                || segment.contains('#')
396	        })
397	    {
398	        return Err(ApiError::new(
399	            ErrorCode::InvalidClaim,
400	            "invalid did:web DID",
401	        ));
402	    }
403	
404	    if segments.len() == 1 {
405	        Ok(format!("https://{host}/.well-known/did.json"))
406	    } else {
407	        let path = segments[1..].join("/");
408	        Ok(format!("https://{host}/{path}/did.json"))
409	    }
410	}
411	
412	fn forbidden_did_web_authority(authority: &str) -> bool {
413	    if authority.contains('@') || authority.contains('[') || authority.contains(']') {
414	        return true;
415	    }
416	
417	    let host = match authority.rsplit_once(':') {
418	        Some((host, port)) if !host.is_empty() && port.parse::<u16>().is_ok() => host,
419	        Some(_) => return true,
420	        None => authority,
421	    };
422	    let host = host.trim_end_matches('.').to_ascii_lowercase();
423	
424	    host == "localhost" || host.ends_with(".localhost") || host.parse::<IpAddr>().is_ok()
425	}
