427	/// Extract the account's `#atproto` repo signing key from a resolved DID document as a
428	/// `did:key:` URI. Walks the W3C `verificationMethod` array for the entry whose `id` ends in
429	/// `#atproto` and returns `did:key:{publicKeyMultibase}`. Returns `None` if absent or malformed.
430	///
431	/// Used by migration-mode `createAccount` to verify a foreign old-PDS-signed service-auth JWT
432	/// against the migrating identity's own signing key.
433	pub fn atproto_verification_key(did_doc: &Value) -> Option<crypto::DidKeyUri> {
434	    did_doc
435	        .get("verificationMethod")?
436	        .as_array()?
437	        .iter()
438	        .find_map(|method| {
439	            let id = method.get("id")?.as_str()?;
440	            if !id.ends_with("#atproto") {
441	                return None;
442	            }
443	            let multibase = method.get("publicKeyMultibase")?.as_str()?;
444	            Some(crypto::DidKeyUri(format!("did:key:{multibase}")))
445	        })
446	}
447	
448	fn also_known_as_handles(did_doc: &Value) -> Vec<String> {
449	    did_doc
450	        .get("alsoKnownAs")
451	        .and_then(Value::as_array)
452	        .into_iter()
453	        .flatten()
454	        .filter_map(Value::as_str)
455	        .filter_map(|alias| alias.strip_prefix("at://"))
456	        .map(ToString::to_string)
457	        .collect()
458	}
