impl From<AuthorityError> for ApiError {
    /// Fallback mapping for callers without their own opaque rejection helper. The two current
    /// callers map `Unauthorized` themselves so the reason reaches their structured warn log.
    fn from(error: AuthorityError) -> Self {
        match error {
            AuthorityError::Unauthorized(_) => ApiError::new(
                ErrorCode::AuthenticationRequired,
                "signing key is not authorized for this account",
            ),
            AuthorityError::Lookup(err) => err,
        }
    }
